'use strict';
// Run after npm test: the input is generated by completing the entire course
// through runtime actions, rather than inventing completion evidence here.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const {chromium} = require('playwright');
const {createServer} = require('./serve-learning-path');
const unit = require('../content/learning-course.json');
const runtime = require('../core/learning-path-runtime');

async function main() {
  const raw = fs.readFileSync('test-results/review-repair/lab-full-course-record.json', 'utf8');
  const envelope = JSON.parse(raw);
  assert.ok(runtime.validRecord(envelope.value, unit));
  assert.equal(Object.keys(envelope.value.completed).length, Object.keys(unit.activities).length);
  const server = createServer();
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage();
    await page.goto('http://127.0.0.1:' + server.address().port);
    await page.waitForSelector('.journey-app');
    const result = await page.evaluate(({raw, unitId}) => {
      const core = window.CanranCore;
      const unit = core.curriculumCatalog.getTeachingUnit(unitId);
      const adapter = core.learningStore.createLocalStorageAdapter(localStorage);
      const key = `poc:learning-path:${unit.unitId}:${unit.experienceRevision}`;
      const original = JSON.parse(raw);
      localStorage.setItem(key, raw);
      localStorage.setItem(key + ':recovery:migration', raw);
      localStorage.setItem(key + ':recovery:quarantine', raw);
      const checkpoint = adapter.checkpoint(key, {expectedRevision: original.revision});
      const committed = adapter.commit(key, {expectedRevision: original.revision, value: original.value});
      const restored = core.learningPathRuntime.createRuntime({unit, adapter}).snapshot(true);
      return {
        checkpoint: checkpoint.status,
        commit: committed.status,
        copies: ['migration', 'backup', 'quarantine'].map(slot => localStorage.getItem(key + ':recovery:' + slot) === raw),
        completed: Object.keys(restored.record.completed).length,
        screen: restored.screen,
        characters: raw.length,
        totalCharacters: Array.from({length: localStorage.length}, (_, i) => localStorage.getItem(localStorage.key(i)).length).reduce((a, b) => a + b, 0)
      };
    }, {raw, unitId: unit.unitId});
    assert.equal(result.checkpoint, 'ok');
    assert.equal(result.commit, 'committed');
    assert.ok(result.copies.every(Boolean));
    assert.equal(result.completed, Object.keys(unit.activities).length);
    assert.equal(result.screen, 'map');
    const report = {status: 'passed', ...result};
    fs.writeFileSync('test-results/review-repair/storage-budget.json', JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify(report, null, 2));
  } finally {
    await browser.close();
    await new Promise(resolve => server.close(resolve));
  }
}
main().catch(error => { console.error(error); process.exitCode = 1; });
